// World map preview on a real Android system (emulator, Android 14, the actual APK and its WebView). The page is driven and measured over DevTools:
// generation time, frame times while panning and zooming at FAR / MEDIUM / CLOSE, memory, screenshots. Emulator = software GL: use the numbers as an upper bound, not as a phone.
const CDP = require('chrome-remote-interface'); const fs = require('fs');
const results = []; let fails = 0, out = {};
const check = (n, ok, info) => { results.push({ n, ok: !!ok }); if (!ok) fails++; console.log((ok ? 'PASS ' : 'FAIL ') + n + (info ? '  — ' + info : '')); };
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  let t = null; for (let i = 0; i < 20 && !t; i++) { try { t = (await CDP.List({ port: 9222 })).find(x => x.type === 'page'); } catch (e) {} if (!t) await sleep(1500); }
  if (!t) { console.log('FAIL no WebView page'); return; }
  const client = await CDP({ port: 9222, target: t, local: true }), { Runtime, Page } = client; await Runtime.enable(); await Page.enable();
  const errors = []; Runtime.exceptionThrown(e => errors.push('exception: ' + (e.exceptionDetails.exception && e.exceptionDetails.exception.description || e.exceptionDetails.text))); Runtime.consoleAPICalled(e => { if (e.type === 'error') errors.push(e.args.map(a => a.value || a.description).join(' ')); });
  const ev = async expr => { const r = await Runtime.evaluate({ expression: '(async () => { ' + expr + ' })()', awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails).slice(0, 300)); return r.result.value; };
  const probe = () => ev(`const c = document.getElementById('c'), g = c.getContext('2d'); let non = 0, n = 0; for (let y = 0; y < c.height; y += Math.max(1, c.height >> 5)) for (let x = 0; x < c.width; x += Math.max(1, c.width >> 4)) { const d = g.getImageData(x, y, 1, 1).data; n++; if (d[0] > 40 || d[1] > 40) non++; } return { non, n, w: c.width, h: c.height, lost: !!(g.isContextLost && g.isContextLost()) };`);
  const shot = async name => { try { const pr = await probe(); console.log('canvas probe ' + name + ': ' + JSON.stringify(pr)); out['probe_' + name] = pr; fs.writeFileSync('results/' + name + '-canvas.png', Buffer.from((await ev(`return document.getElementById('c').toDataURL('image/png');`)).split(',')[1], 'base64')); } catch (e) { console.log('probe failed ' + name + ' ' + e.message); } try { const r = await Page.captureScreenshot({ format: 'png' }); fs.writeFileSync('results/' + name + '.png', Buffer.from(r.data, 'base64')); } catch (e) { console.log('shot failed ' + name); } };
  let ready = false; for (let i = 0; i < 60 && !ready; i++) { ready = await ev('return !!window.__wp;').catch(() => false); if (!ready) await sleep(1000); } check('the preview page is running in the WebView', ready);
  if (!ready) return;
  const env = await ev('return { ua: navigator.userAgent, dpr: devicePixelRatio, w: innerWidth, h: innerHeight, mem: performance.memory ? Math.round(performance.memory.usedJSHeapSize / 1048576) : null };'); console.log('ENV ' + JSON.stringify(env)); out.env = env;
  let done = false; for (let i = 0; i < 240 && !done; i++) { done = await ev('return window.__wp.genLeft() === 0;'); if (!done) { if (i % 15 === 0) console.log('generating: ' + await ev('return window.__wp.ready();') + '/600 after ' + i + ' s'); await sleep(1000); } }
  const gen = await ev('return { ms: window.__wp.stats.genDoneMs, built: window.__wp.ready() };'); out.generation = gen; check('overview + starter regions are computed in the workers', done, 'ready ' + gen.ms + ' ms after page start (software-rendered emulator), first images ' + gen.built);
  const start = await ev('const w = window.__wp.world, r = w.regions.find(r => r.starter); return { x: r.x0 + 160, y: r.y0 + 160 };');
  // baseline: how fast can this WebView present frames at all (no map)? separates emulator limits from map cost
  const base = await ev(`return await new Promise(res => { const c = document.createElement('canvas'); c.width = innerWidth * 2; c.height = innerHeight * 2; c.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;z-index:-1'; document.body.appendChild(c); const g = c.getContext('2d'), d = []; let last = performance.now(), t0 = last, n = 0; (function f() { const t = performance.now(); d.push(t - last); last = t; g.fillStyle = 'hsl(' + (n++ * 7 % 360) + ',40%,30%)'; g.fillRect(0, 0, c.width, c.height); if (t - t0 < 2500) requestAnimationFrame(f); else { c.remove(); d.shift(); d.sort((a, b) => a - b); res({ fps: d.length / 2.5, p95: d[Math.floor(d.length * .95)] }); } })(); });`);
  out.baseline = base; console.log('BASELINE blank full-screen canvas, no map: ' + base.fps.toFixed(1) + ' fps, p95 ' + base.p95.toFixed(0) + ' ms (this is the emulator ceiling)');
  // warm-up pan so the adaptive resolution settles, then measure
  await ev(`window.__wp.goto(960, 640, 0.30);`); await ev(`return await new Promise(res => { const w = window.__wp; let n = 0, t0 = performance.now(); (function f() { w.goto(w.cam.x + (n++ % 2 ? -4 : 4), w.cam.y + 2); if (performance.now() - t0 < 4000) requestAnimationFrame(f); else res(1); })(); });`);
  out.dprAfterWarmup = await ev('return { dpr: window.__wp.dpr(), changes: window.__wp.stats.dprChanges };'); console.log('canvas resolution after warm-up: ' + JSON.stringify(out.dprAfterWarmup));
  const level = async (name, z, x, y) => {
    await ev(`window.__wp.goto(${x}, ${y}, ${z});`); let left = 1; for (let i = 0; i < 90 && left; i++) { await sleep(300); left = await ev('return window.__wp.pending();'); }
    const d = await ev('const w = window.__wp, a = []; for (let i = 0; i < 40; i++) { const t = performance.now(); w.draw(); a.push(performance.now() - t); } a.sort((p, q) => p - q); return { avg: a.reduce((p, q) => p + q, 0) / a.length, p95: a[Math.floor(a.length * .95)], max: a[a.length - 1], level: w.level() };');
    const pan = await ev(`return await new Promise(res => { const w = window.__wp, d = []; let last = performance.now(), n = 0, t0 = last; (function f() { const t = performance.now(); d.push(t - last); last = t; w.goto(w.cam.x + (n % 2 ? -1 : 1) * 6 / (w.cam.z * 40 + 1), w.cam.y + 3 / (w.cam.z * 40 + 1)); n++; if (t - t0 < 3000) requestAnimationFrame(f); else { d.shift(); d.sort((a, b) => a - b); res({ frames: d.length, fps: d.length / 3, avg: d.reduce((a, b) => a + b, 0) / d.length, p95: d[Math.floor(d.length * .95)], max: d[d.length - 1], long: d.filter(x => x > 50).length }); } })(); });`);
    out[name] = { draw: d, pan }; await shot('map-' + name);
    check(name.toUpperCase() + ': level is ' + name.toUpperCase() + ', draw avg ' + d.avg.toFixed(1) + ' ms (p95 ' + d.p95.toFixed(1) + ', max ' + d.max.toFixed(1) + '), panning ' + pan.fps.toFixed(0) + ' fps, frame p95 ' + pan.p95.toFixed(0) + ' ms, max ' + pan.max.toFixed(0) + ' ms, frames over 50 ms: ' + pan.long, d.level === (name === 'far_regions' ? 'FAR' : name.toUpperCase()));
  };
  await level('far', 0.0045, 960, 640); await level('far_regions', 0.03, 960, 640); await level('medium', 0.30, start.x, start.y); await level('close', 1.0, start.x, start.y);
  // long pan across the world (CLOSE and MEDIUM): ~1500 tiles in 8 s, detail images are built on the way
  const frames = (name, body, dur) => ev(`return await new Promise(res => { const w = window.__wp, d = [], h0 = w.stats.imgs, m0 = performance.memory ? performance.memory.usedJSHeapSize : 0; let last = performance.now(), t0 = last; const lv = {}; (function f() { const t = performance.now(); d.push(t - last); last = t; ${body}; const L = w.level(); (lv[L] = lv[L] || []).push(d[d.length - 1]); if (t - t0 < ${dur}) requestAnimationFrame(f); else { d.shift(); const st = a => { a = a.slice().sort((x, y) => x - y); return a.length ? { n: a.length, fps: +(1000 / (a.reduce((p, q) => p + q, 0) / a.length)).toFixed(1), p95: +a[Math.floor(a.length * .95)].toFixed(1), max: +a[a.length - 1].toFixed(1), over50: a.filter(x => x > 50).length } : null; }; const per = {}; for (const k in lv) per[k] = st(lv[k]); res({ all: st(d), per, built: w.stats.imgs - h0, memDeltaMB: performance.memory ? +((performance.memory.usedJSHeapSize - m0) / 1048576).toFixed(1) : null, cam: { x: Math.round(w.cam.x), y: Math.round(w.cam.y), z: +w.cam.z.toFixed(3) } }); } })(); });`);
  const run = async (name, dur, body) => { const r = await frames(name, body, dur); r.name = name; out[name] = r; return r; };
  const sh2 = (r) => (r.all ? r.all.fps + ' fps, p95 ' + r.all.p95 + ' ms, max ' + r.all.max + ' ms, frames > 50 ms: ' + r.all.over50 + '/' + r.all.n : 'no frames');
  await ev('window.__wp.goto(60, 60, 0.35);'); await sleep(2500);
  let r = await run('longpan_medium', 8000, 'const k = (t - t0) / 8000; w.goto(60 + k * 1500, 60 + k * 1000, 0.35)'); check('long pan at MEDIUM across the world (' + r.cam.x + ',' + r.cam.y + '): ' + sh2(r) + ', detail images built ' + r.built + ', heap ' + r.memDeltaMB + ' MB', !!r.all);
  await ev('window.__wp.goto(1800, 1200, 1.0);'); await sleep(2500);
  r = await run('longpan_close', 8000, 'const k = (t - t0) / 8000; w.goto(1800 - k * 1400, 1200 - k * 900, 1.0)'); check('long pan at CLOSE (400 tiles): ' + sh2(r) + ', detail images built ' + r.built + ', heap ' + r.memDeltaMB + ' MB', !!r.all);
  r = await run('zoom_in_out', 10000, 'const k = (t - t0) / 10000, e = k < .5 ? k * 2 : (1 - k) * 2; w.goto(960, 640, 0.0045 * Math.pow(1 / 0.0045, e))'); check('zoom out->in->out over the whole range, per level: ' + JSON.stringify(Object.fromEntries(Object.entries(r.per).map(([k, v]) => [k, v && v.fps + 'fps/p95 ' + v.p95 + 'ms']))) + ' · ' + sh2(r), !!r.all);
  const tm = await ev('return { firstDrawMs: window.__wp.stats.firstDrawMs, genDoneMs: window.__wp.stats.genDoneMs, chunks: window.__wp.ready(), world: [window.__wp.world.W, window.__wp.world.H], scale: window.__wp.world.scale(), regions: window.__wp.world.regions.length, cached: window.__wp.world.cachedChunks(), sites: window.__wp.world.allSites().length };'); out.timing = tm; check('map first visible ' + tm.firstDrawMs + ' ms after page start; whole world ' + tm.genDoneMs + ' ms; world ' + tm.world.join('x') + ' tiles = ' + tm.scale.toFixed(1) + 'x the 140x88 map; ' + tm.chunks + ' chunks, ' + tm.regions + ' regions, ' + tm.sites + ' oil sites', tm.chunks === 600 && tm.scale > 190);
  await ev('window.__wp.ui.scale = true; window.__wp.goto(window.__wp.cam.x, window.__wp.cam.y, 0.9);'); await sleep(1500); await shot('map-scale-chart'); await ev('window.__wp.ui.scale = false;');
  const mem = await ev('return performance.memory ? Math.round(performance.memory.usedJSHeapSize / 1048576) : null;'); out.memoryMB = mem; check('JS heap after the whole test: ' + mem + ' MB', mem == null || mem < 500);
  const worst = Math.max(out.far.draw.avg, out.medium.draw.avg, out.close.draw.avg); check('draw time stays interactive at every level (avg < 60 ms even on the software emulator)', worst < 60, 'worst avg ' + worst.toFixed(1) + ' ms');
  check('no JavaScript errors', errors.length === 0, errors.slice(0, 3).join(' | '));
  fs.writeFileSync('results/map-perf.json', JSON.stringify(out, null, 1)); console.log('MAP SUMMARY ' + results.filter(r => r.ok).length + '/' + results.length + ' PASS'); await client.close();
})().catch(e => { console.log('FAIL crashed: ' + e.message); });
